function adModeActive(){return sidebar==='add'&&category==='ads'?adMode:null;}
let slotCache={project:null,mode:null,slots:[]};
function adSlots(){const mode=adModeActive();if(slotCache.project===project&&slotCache.mode===mode)return slotCache.slots;const slots=computeAdSlots(mode);slotCache={project,mode,slots};return slots;}
function computeAdSlots(mode){if(mode==='remove')return project.items.filter(o=>o.kind==='ad').map(o=>({id:o.id,hostId:o.hostId,face:o.face,slot:o.slot}));if(mode!=='add')return [];
 const out=[];for(const host of project.items.filter(o=>o.kind==='module'))for(const slot of ['top','bottom'])for(const face of Object.keys(FACES)){const item=attachAd({...template('ad',null,slot),id:`slot-${host.id}-${face}-${slot}`,wrap:false,seamless:false},host,face),items=[...project.items,item];if(validateBuilding(items))continue;if(!adRenderGroups(items).some(g=>g.adIds.includes(item.id)))continue;out.push({hostId:host.id,face,slot,item});}return out;}
