const coarsePointer=()=>!!globalThis.matchMedia?.('(pointer:coarse)')?.matches;
const walkLocked=()=>!!engine&&globalThis.document?.pointerLockElement===engine.element;
let lockBlocked=false;
function markLockBlocked(){if(walkLocked())return;lockBlocked=true;root.classList.toggle('fb-walk-free',true);renderWalkPause();}
function requestWalkLock(){if(coarsePointer())return;try{const r=engine?.element?.requestPointerLock?.();r?.catch?.(markLockBlocked);}catch{markLockBlocked();}setTimeout(()=>{if(walking&&!walkLocked())markLockBlocked();},450);}
function renderWalkPause(){const box=$('.fb-walk-paused');if(box)box.hidden=true;}
function walkModules(){return project.items.filter(o=>o.kind==='module');}
function enterWalkAt(x,y){if(!engine?.walkStartAt)return;cancelPaste?.();adMode=null;if(tool!=='select')changeTool('select');hideContext();if(!walking)walkSaved=engine.captureView?.();engine.setWalkPrompt?.(showWalkPrompt);if(!engine.walkStartAt(x,y)){notify('Buradan gezintiye çıkılamaz. Yeşil görünen bir yere bırakın.',true);return;}walkEntered();}
function walkEntered(){walkLookReadyAt=Date.now()+350;lockBlocked=false;root.classList.remove('fb-walk-free');walking=true;view='inside';root.classList.add('fb-walking');render();const hint=$('.fb-walk-hint');if(hint){hint.classList.remove('fb-faded');clearTimeout(walkHintTimer);walkHintTimer=setTimeout(()=>hint.classList.add('fb-faded'),6500);}engine.element.focus?.({preventScroll:true});requestWalkLock();renderWalkPause();}
